CREATE TABLE IF NOT EXISTS rumo10_historico_encerrado (carreira_id BIGINT UNSIGNED PRIMARY KEY, conta_id BIGINT UNSIGNED NOT NULL, encerrada_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, dados_json JSON NOT NULL, bytes_detalhes BIGINT UNSIGNED NOT NULL DEFAULT 0, bytes_resumo INT UNSIGNED NOT NULL, INDEX(conta_id,encerrada_em), FOREIGN KEY(carreira_id) REFERENCES rumo10_carreiras(id) ON DELETE CASCADE, FOREIGN KEY(conta_id) REFERENCES rumo10_contas(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
